 * TF2 ship the same `changeme12` as their admin/RCON password.
 */
export function adminSecretFieldsToMint(
  family: string | null,
  rawSetupScript: string | null,
  gameConfig: Record<string, unknown> | null | undefined,
): string[] {
  if (!family || !rawSetupScript) return [];
  const schema = schemaFor(family);
  if (!schema) return [];
  const out: string[] = [];
  for (const f of schema.fields) {
    if (f.type !== "string") continue;
    const envKey = f.envKey ?? f.key;
    if (!isAdminSecretEnvKey(envKey)) continue;
    const current = scriptEnvValue(rawSetupScript, envKey);
    if (current === null || !WEAK_DEFAULT_SECRETS.has(current)) continue;
    const chosen = gameConfig ? gameConfig[f.key] : undefined;
    if (chosen !== undefined && chosen !== null && String(chosen).trim() !== "" && !WEAK_DEFAULT_SECRETS.has(String(chosen))) continue;
    out.push(f.key);
  }
  return out;
}

/**
 * Backstop for admin/RCON env vars with NO schema field (nothing can be
 * persisted for the customer): if the final script still carries a weak
 * shared default, replace it with a fresh per-server value. Same
 * rotate-per-build rule as Palworld/Rust/CS2 below.
 */
export function rotateWeakAdminSecrets(setupScript: string): string {
  const re = /-e\s+([A-Z0-9_]+)=('[^']*'|"[^"]*"|\S*)/g;
  const secrets: Record<string, string> = {};
  let m: RegExpExecArray | null;
  while ((m = re.exec(setupScript))) {
    const value = m[2].replace(/^['"]|['"]$/g, "");
    if (isAdminSecretEnvKey(m[1]) && WEAK_DEFAULT_SECRETS.has(value)) secrets[m[1]] = generatePassword();
  }
  return Object.keys(secrets).length ? applyGameControlSecrets(setupScript, secrets) : setupScript;
}

/**
 * Env vars that name an ACCOUNT (an admin user name), where an empty value is
 * not "no account" but an invalid one the game refuses to start with.
 */
export function isIdentityEnvKey(envKey: string): boolean {
  return /(^|_)(ADMIN_?)?USER(_?NAME)?$/.test(envKey) || /ADMIN_?NAME$/.test(envKey);
}

/** The value a blank identity field gets: the catalog's own (if real), else "admin". */
export const DEFAULT_ADMIN_USERNAME = "admin";

/**
 * Schema fields of this family that name an admin ACCOUNT, are docker-env-driven
 * in its script, and are blank in the server's config — with the value
 * provision() should persist for each (so the customer sees the real admin user
 * name in Settings, and every later rebuild uses it). Pairs with
 * adminSecretFieldsToMint, which handles the matching password.
 */
export function blankIdentityDefaults(
  family: string | null,
  rawSetupScript: string | null,
  gameConfig: Record<string, unknown> | null | undefined,
): Record<string, string> {
  if (!family || !rawSetupScript) return {};
  const schema = schemaFor(family);
  if (!schema) return {};
  const out: Record<string, string> = {};
  for (const f of schema.fields) {
    if (f.type !== "string") continue;
    const envKey = f.envKey ?? f.key;
    if (!isIdentityEnvKey(envKey)) continue;
    const current = scriptEnvValue(rawSetupScript, envKey);
    if (current === null) continue;
    const chosen = gameConfig ? gameConfig[f.key] : undefined;
    if (chosen !== undefined && chosen !== null && String(chosen).trim() !== "") continue;
    out[f.key] = current.trim() !== "" ? current.trim() : DEFAULT_ADMIN_USERNAME;
  }
  return out;
}

/** One per-server secret, same generator as the family-specific ones below. */
export function mintGameSecret(): string {
  return generatePassword();
}

/**
 * Build the fully-substituted, systemd-wrapped game install script for a
 * server: variant → config values → Minecraft's java image tag → per-server
 * secrets → wrapped into a `docker create` + generated unit (see
 * `wrapDockerGameService`). Returns null for a non-game template (or one with
 * no setupScript at all).
 *
 * Extracted from `buildCloudInit` (2026-09-24) so `gameReinstall` (worker/
 * game-control.ts's GAME_REINSTALL handler) can regenerate the IDENTICAL
 * script an original PROVISION would have used — including reapplying
 * whatever gameVariant/gameConfig the customer has set SINCE the original
 * provision (a reinstall is exactly the moment a setting that silently never
 * applied gets a real chance to take effect), and minting BRAND NEW
 * per-server secrets for palworld/rust/cs2 on every call — the same
 * "reinstall rotates credentials, never keeps the old ones" rule
 * `reinstall()`'s own comment (worker/index.ts) applies to the VPS root
 * password.
 */
export function buildGameSetupScript(server: {
  /** Needed by fivem (per-server derived secrets); every real caller passes the Server row. */
  id?: string;
  osTemplate: { setupScript: string | null; family: string | null };
  gameVariant?: string | null;
  gameConfig?: unknown;
  /** Minecraft only: an exact mirrored jar to stage + pin (worker/mcjar-pin.ts#mcJarPinForSetup), or null for upstream behaviour. */
  __mcJarPin?: PinPlan | null;
  // The VM's real RAM (GamePlan.ramMB, else the VPS plan's). Optional: a
  // caller that doesn't load the plan (GAME_REINSTALL today) keeps the
  // catalog's heap exactly as before.
  // Index signature: callers pass their own partial selects (GAME_REINSTALL's
  // gamePlan is `{ gameFamily }`), which TS's weak-type check would reject.
  gamePlan?: { ramMB?: number | null; [k: string]: unknown } | null;
  plan?: { ramMB?: number | null; [k: string]: unknown } | null;
}): string | null {
  if (!server.osTemplate.setupScript) return null;
  const scriptWithDocker = skipDockerInstallIfPresent(server.osTemplate.setupScript);
  const scriptWithVariant = applyGameVariant(scriptWithDocker, server.osTemplate.family, server.gameVariant ?? null);
  const scriptWithConfig = applyGameConfigEnv(
    scriptWithVariant,
    server.osTemplate.family,
    server.gameConfig as Record<string, unknown> | null,
    // the 4.2 GB golden template 67.7s, linked 2.1s (stock 9000 full: 24.5s).
    const linked = cloneSource.golden && linkedCloneAllowed({
      enabled: process.env.NXEON_GOLDEN_LINKED_CLONE === "1",
      templateDiskSpec: goldenConfig?.scsi0 ?? null,
      targetStorage: storage,
    });
    const cloneUpid = await conn.post(
      `/nodes/${conn.node}/qemu/${baseVmid}/clone`,
      linked ? { newid: vmid, name: server.hostname, full: 0 } : { newid: vmid, name: server.hostname, full: 1, storage },
    );
    await conn.waitForTask(cloneUpid, 600_000);
  }

  // Per-server cloud-init snippet (base + panel/app install + add-ons).
  //
  // This write used to be `.catch`'d to a console line (M7 #10). It must not be:
  // the very next config POST sets `cicustom: vendor=…/nxeon-<vmid>.yaml`, so a
  // failed write hands the VM a vendor-data file that does not exist. Root SSH
  // config, the guest agent, the setup script, START-WITH-CLAUDE.md and the MOTD
  // all silently vanish, and the customer is still told the server is ready.
  // Failing here is recoverable — the job retries, and the clone above is
  // idempotent. Continuing is not.
  // NxCloud hook: if this VM is the backing box for a managed Nextcloud instance,
  // generate its one-time admin password (persisted, once) and get the idempotent
  // install script to bake into cloud-init. Null for an ordinary VPS.
  // Per-server admin/RCON passwords for families whose catalog script ships a
  // shared placeholder (`changeme12`) — see adminSecretFieldsToMint. Minted
  // ONCE and persisted into gameConfig BEFORE the snippet is built, so the
  // customer can read it in Settings, applyGameConfigEnv substitutes it like
  // any checkout value, and a PROVISION retry / GAME_REINSTALL reuses it.
  if (isGame) {
    const fam = server.osTemplate?.family ?? null;
    const cfg0 = ((server.gameConfig as Record<string, unknown> | null) ?? {}) as Record<string, unknown>;
    const toMint = adminSecretFieldsToMint(fam, server.osTemplate?.setupScript ?? null, cfg0);
    // Blank admin ACCOUNT names (PZ's ADMIN_USERNAME="" crash loop, 2026-10-02)
    // get the catalog's real value (or "admin"), persisted like a minted secret.
    const identity = blankIdentityDefaults(fam, server.osTemplate?.setupScript ?? null, cfg0);
    if (toMint.length > 0 || Object.keys(identity).length > 0) {
      const next = { ...cfg0, ...identity };
      for (const k of toMint) next[k] = mintGameSecret();
      await db.server.update({ where: { id: server.id }, data: { gameConfig: next as any } });
      (server as any).gameConfig = next;
      (server as any).__mintedConfigKeys = toMint;
      if (toMint.length) console.log(`[worker] provision ${server.hostname}: minted per-server ${toMint.join(", ")} (catalog default was a shared placeholder)`);
      if (Object.keys(identity).length) console.log(`[worker] provision ${server.hostname}: defaulted blank ${Object.keys(identity).join(", ")} (a blank admin account name stops the game from starting)`);
    }
  }
  (server as any).__nxcloudSetup = await nxcloudSetupForServer(server);
  // Live telemetry: mint a fresh per-server shipper token and persist its hash
  // BEFORE building cloud-init, so the config the agent boots with matches what
  // the ingest route will look up (lib/telemetry-token.ts). Re-provisioning
  // (this code path runs again) simply mints a new token, invalidating the old
  // one — no rotation UI needed for that case.
  //
  // RE-ENTRANCY (2026-10-01): NOT on a retry whose guest is already running.
  // Its cloud-init already ran with the PREVIOUS attempt's snippet (vendor data
  // is per-instance and the VM is not rebooted on retry), so its shipper holds
  // the previous token; re-minting here replaced the stored hash with one the
  // guest never received, and that server's telemetry 401'd forever after any
  // retried provision. A VM that exists but never started (crash between clone
  // and start) still boots with THIS snippet, so it does get a fresh token.
  const guestAlreadyBooted =
    vmAlreadyExists &&
    !!(server as any).telemetryTokenHash &&
    (await conn.vmStatus(vmid).then((st: { status?: string } | null) => st?.status === "running").catch(() => false));
  (server as any).__telemetryToken = guestAlreadyBooted ? null : await mintServerTelemetryToken(server.id);
  // Minecraft server-software mirror: pin the exact jar (null → old upstream behaviour). See worker/mcjar-pin.ts.
  (server as any).__mcJarPin = await mcJarPinForSetup(server as any);

  await step("Configuring the network…");
  // The vendor snippet must land on THIS SERVER'S OWN NODE's filesystem, but
  // there is exactly one worker process for the whole platform and it runs
  // only on the primary — it has no local filesystem access to a different
  // physical node at all. The primary writes its own snippet directly
  // (SNIPPET_DIR); a non-primary node's snippet is written remotely through
  // its own node-agent (Phase 3 of the 2026-09-05 multi-node hardening plan —
  // see docs/DOCUMENTATION.md's "Multi-node synergy" section) using that
  // node's own snippet-capable storage (isPrimary ? "backup" : storageHdd —
  // the same divergence fixed for backups the same day). If the agent isn't
  // configured yet for that node (no token set, e.g. a node onboarded before
  // Phase 3 shipped, or before its agent step was run), this DEGRADES rather

