import { AppLogo } from "@/components/ui/AppLogo";
import { fmtMoney } from "@/components/ui/primitives";
import type { ServiceRow, ServiceStatus } from "@/lib/nx/services";

export const STATUS_STYLE: Record<ServiceStatus, { dot: string; ink: string; chip: string }> = {
  running:   { dot: "bg-emerald-400", ink: "text-emerald-300", chip: "border-emerald-400/30 bg-emerald-950/70" },
  pending:   { dot: "bg-amber-400 animate-pulse", ink: "text-amber-300", chip: "border-amber-400/30 bg-amber-950/70" },
  stopped:   { dot: "bg-rose-400", ink: "text-rose-300", chip: "border-rose-400/30 bg-rose-950/70" },
  suspended: { dot: "bg-orange-400", ink: "text-orange-300", chip: "border-orange-400/30 bg-orange-950/70" },
  error:     { dot: "bg-red-400", ink: "text-red-300", chip: "border-red-400/30 bg-red-950/70" },
  cancelled: { dot: "bg-slate-400", ink: "text-slate-300", chip: "border-slate-400/25 bg-slate-950/70" },
};

/** The service mark that sits under the preview, one per product. */
const KIND_MARK: Record<ServiceRow["kind"], { mark: string; ring: string }> = {
  vps:     { mark: "vps",     ring: "border-[#3d7bff]/40 bg-[#3d7bff]/12" },
  game:    { mark: "game",    ring: "border-[#a86bff]/40 bg-[#a86bff]/12" },
  hosting: { mark: "hosting", ring: "border-[#3ec9ff]/40 bg-[#3ec9ff]/12" },
  free:    { mark: "game",    ring: "border-emerald-500/40 bg-emerald-500/12" },
  domain:  { mark: "domains", ring: "border-amber-400/40 bg-amber-400/12" },
  email:   { mark: "email",   ring: "border-fuchsia-400/40 bg-fuchsia-400/12" },
};

function fmtDate(iso: string): string {
  return new Date(iso).toLocaleDateString("en-US", {
    year: "numeric", month: "short", day: "numeric", timeZone: "UTC",
  });
}

/** How the renewal total is qualified. `renewalCharge` returns the charge for
 *  the WHOLE term, and a term can be 1, 3, 12, 24 or 36 months, so anything but
 *  "/mo" and "/yr" has to say how many months it actually buys. */
function termSuffix(months: number): string {
  if (months === 12) return "/yr";
  if (months <= 1) return "/mo";
  if (months % 12 === 0) return `/${months / 12}yr`;
  return `/${months}mo`;
}

function daysUntil(iso: string): number {
  return Math.ceil((new Date(iso).getTime() - Date.now()) / 86_400_000);
}

/* ── the picture every card leads with ────────────────────────────────────
   A stock plate underneath, and — for a live hosting plan — the customer's
   own site framed over it. The frame is inert: no scripts, no pointer
   events, no tab stop. A site that refuses to be framed simply never paints,
   and the plate stays. Nothing here stands in for a site that isn't there. */
function Preview({ row }: { row: ServiceRow }) {
  return (
    <span className="relative block h-full w-full overflow-hidden bg-[#050d20]">
      {/* eslint-disable-next-line @next/next/no-img-element -- art + customer uploads, both outside the optimizer */}
      />
    </button>
  );
}

export function ServiceCard({ row, onChangeImage }: { row: ServiceRow; onChangeImage: () => void }) {
  const st = STATUS_STYLE[row.status];
  const mark = KIND_MARK[row.kind];
  const days = row.renewalIso ? daysUntil(row.renewalIso) : null;
  const soon = days !== null && days <= 7 && row.status !== "cancelled";

  return (
    <article className="group flex flex-col overflow-hidden rounded-[17px] border border-rim-hi bg-[linear-gradient(180deg,rgba(10,22,48,.55),rgba(2,7,20,.72))] p-[5px] transition duration-300 hover:border-brand-400/45 hover:shadow-[0_0_0_1px_rgba(72,148,255,.12),0_18px_44px_-24px_rgba(72,148,255,.5)]">
      {/* ── preview ──────────────────────────────────────────────────── */}
      {/* nx-dark-island: this well always sits over unpredictable photographic
          art (stock rack plates, a customer's framed site, Minecraft preview
          renders), so its overlaid chips (status pill, "..." menu button) are
          deliberately fixed-dark regardless of theme — freezing the tokens
          here also opts this subtree OUT of globals.css's generic
          bg-white//border-white//text-white/NN light-mode sweep, which
          otherwise repaints `text-white/85` on the menu button as dark ink,
          making its "..." glyph disappear against its own dark-glass face. */}
      <div className="nx-dark-island relative aspect-[16/4] w-full overflow-hidden rounded-[13px]">
        <Preview row={row} />

        <div className="absolute left-2.5 top-2.5 flex items-center gap-1.5">
          <span className={"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[11px] font-bold backdrop-blur " + st.chip + " " + st.ink}>
            <span className={"h-[6px] w-[6px] flex-none rounded-full " + st.dot} />
            {row.statusLabel}
          </span>
          {row.renewalCents === null && (
            <span className="rounded-full border border-white/15 bg-black/55 px-2.5 py-1 text-[11px] font-bold text-white/90 backdrop-blur">
              Free Plan
            </span>
          )}
        </div>

        <div className="absolute right-2.5 top-2.5">
          <CardMenu row={row} onChangeImage={onChangeImage} />
        </div>
      </div>

      {/* ── body ─────────────────────────────────────────────────────── */}
      <div className="flex flex-1 flex-col gap-3 px-3 pb-3 pt-3.5">
        <div className="flex items-center gap-3">
          <span className={"grid h-[44px] w-[44px] flex-none place-items-center rounded-[13px] border " + mark.ring}>
            <SvcIcon name={mark.mark} size={28} />
          </span>
          <span className="flex min-w-0 flex-col">
            <Link href={row.href} className="truncate text-[15.5px] font-bold leading-tight text-white transition hover:text-brand-300">
              {row.name}
            </Link>
            <span className="mt-0.5 truncate text-[12px] text-[#6f92d6]">
              {row.typeLabel}
              {row.specs ? ` · ${row.specs}` : ""}
            </span>
          </span>
        </div>

        <div className="flex min-w-0 items-center gap-2.5">
          {row.location ? (
            <span className="flex min-w-0 flex-none items-center gap-1.5 text-[12.5px] text-tx-dim">
              <CountryFlag code={row.location.country} size={17} />
              <span className="truncate">{row.location.label}</span>
            </span>
          ) : (
            <span className="flex flex-none items-center gap-1.5 text-[12.5px] text-tx-faint">
              <Icon name="pin" size={12} tone="inherit" />
              &mdash;
            </span>
          )}
          <span className="ml-auto min-w-0">
            <Address row={row} />
          </span>
        </div>

        <div className="mt-auto flex items-center gap-3 pt-0.5">
          <span className="flex min-w-0 flex-col">
            <span className={"truncate text-[12px] " + (soon ? "font-semibold text-rose-300" : "text-[#6f92d6]")}>
              {row.renewalIso ? `Renews ${fmtDate(row.renewalIso)}` : "Renews —"}
            </span>
            <span className="mt-0.5 truncate text-[13.5px] font-bold text-white">
              {row.renewalCents === null
                ? "Free Plan"
                : <>{fmtMoney(row.renewalCents)}<span className="font-medium text-tx-faint">{termSuffix(row.termMonths)}</span></>}
            </span>
          </span>
          <Link
            href={row.href}
            className="nx-svc-manage ml-auto inline-flex flex-none items-center gap-2 rounded-[11px] border border-[#2a55b5] bg-[linear-gradient(180deg,rgba(24,48,110,.75),rgba(11,24,60,.75))] px-4 py-2 text-[13px] font-semibold text-white transition hover:border-brand-400 hover:bg-[rgba(72,148,255,.16)]"
          >
            Manage
            <span aria-hidden className="transition-transform group-hover:translate-x-0.5">→</span>
          </Link>
        </div>
      </div>
    </article>
  );
}
