  const totalServiceCount = servers.length + hostingCount + (hasFree ? 1 : 0);
  const stats: Stat[] = [
    {
      label: "Total Services", value: String(totalServiceCount), icon: "server", tone: "c",
      delta: newThisMonth > 0 ? { dir: "up", text: String(newThisMonth) } : undefined,
      foot: "Active services",
    },
    { label: "Monthly Spend", value: money(monthlySpendCents), icon: "card", tone: "", delta: spendDelta, foot: "vs. last month" },
    {
          header={header}
          /* The facts the hero does NOT already show, so Overview stops
             repeating identity back at the reader one card below it. */
          facts={{
            planName: server.gamePlan?.name ?? server.plan.name,
            planSpec: server.gamePlan
