              : `${server.plan.cpuCores} vCPU · ${Math.round(server.plan.ramMB / 1024)} GB RAM`,
            createdLabel: server.createdAt.toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" }),
            node: server.node?.name ?? null,
            serverIdShort: `#${server.id.slice(0, 10)}`,
            renewalLabel: server.expiresAt
