export async function resolveGameIntentRegion(
  intent: GameOrderIntent,
  quote: { ramMB: number; osTemplateId: string },
  userId: string,
): Promise<GameOrderIntent> {
  const tplRow = await db.osTemplate.findUnique({ where: { id: quote.osTemplateId }, select: { vmid: true, baseVmid: true } });
