/**
 * WHAT A PLAYER NEEDS TO CONNECT, per game family — one pure, tested table that the
 * admin partner-grant form, the grant server-side guard, the grant handoff summary,
 * the customer's "Join details" card and scripts/audit-grants.ts all read, so none of
 * them can disagree about which fields make a server joinable.
 *
 * Background (2026-10-02, docs/GRANT-CONNECT-AUDIT.md): a granted Core Keeper server
 * was created with no Connect Code and no password, a granted Terraria server with no
 * password, because the grant form only offered game/plan/term/region. The normal wizard
 * folds every non-required field under "Advanced", so a normal customer can leave them
 * blank too — but a customer chooses to; a creator we hand a server to must be able to
 * connect without asking us for secrets. For a GRANT, the join password and any
 * connect/join code are therefore treated as required (with a generated default).
 *
 * Plain module: no I/O, no secrets, safe in client components, server actions, scripts.
 * Field keys are the schema keys of lib/game-config.ts (tests assert every key exists).
 */
import { GAME_CONFIG_SCHEMAS, type ConfigField } from "./game-config";
import { fieldProblem, suggestGameCode, suggestPassword, suggestUuid } from "./game-field-rules";
import { HOSTNAME_CONNECT_FAMILIES, joinPortsFor, type GameFamily } from "./games";

export type CodeGen = "gameid" | "uuid";

export type ConnectSpec = {
  /** Schema key of the JOIN password players type to enter (absent = the schema has none). */
  join?: string;
  /** Hard upper length of that join password where the game enforces one. */
  joinMax?: number;
  /** Connect/join codes or world IDs the server needs (generated for a grant). */
  codes?: { key: string; gen: CodeGen }[];
  /** Admin/RCON/moderator secrets (generated default, optional). */
  admin?: string[];
  /** Owner / admin / allow-list identity fields (Steam IDs, usernames) — the creator's own, never generated. */
  ids?: string[];
  /** Workshop / mod collections. */
  workshop?: string[];
  /** Plain note: how players find the server, or why the schema cannot express a join password. */
  note?: string;
  /** A real gap the schema/worker cannot close from the grant path (listed in the audit). */
  gap?: string;
};

export const CONNECT_SPECS: Record<string, ConnectSpec> = {
  minecraft: { ids: ["white-list"], note: "Players connect with the play subdomain (no port). No join password exists; use the allow-list (Settings) to restrict access." },
  rust: { note: "Players connect with address:port (client.connect or the server list by name). The schema has no join password; RCON password is generated by the worker." },
  valheim: { join: "SERVER_PASS", ids: ["ADMINLIST_IDS", "PERMITTEDLIST_IDS"], note: "Join by address:2456 or the server-list name; with Crossplay on, consoles use the join code printed in the server log." },
  cs2: { join: "CS2_PW", admin: ["CS2_RCONPW"], note: "console: connect <subdomain>.play.nxeon.cloud; password <pw>." },
  palworld: { gap: "The schema has no server-password field (the image supports SERVER_PASSWORD but Nxeon exposes only the in-game Community Servers listing + admin RCON), so a granted Palworld server is open to anyone who finds it. Needs a schema field + applier before a grant can set one.", note: "PC joins by address:8211; consoles search the Community Servers list by exact server name." },
  ark: { join: "SERVER_PASSWORD", admin: ["ADMIN_PASSWORD"], workshop: ["GAME_MOD_IDS"], note: "Join via Steam > Add server, address:7777 (or play subdomain + port)." },
  satisfactory: { gap: "No join password exists in the schema: Satisfactory is claimed in-game via Server Manager (the first player to claim sets the admin password).", note: "Players add the server in Server Manager with address:7777; the creator must claim it first." },
  projectzomboid: { admin: ["ADMIN_USERNAME", "ADMIN_PASSWORD", "RCON_PASSWORD"], gap: "The schema has no server join-password field. Admin account is minted/defaulted by the worker." , note: "Join by address:16261 with the admin account to get admin rights." },
  sdtd: { join: "ServerPassword", note: "Join via address:26900; the Sandbox code (optional) carries the difficulty settings." },
  vrising: { join: "Password", admin: ["Rcon__Password"], note: "Join via address:9876 (Direct Connect) or the server list by name." },
  enshrouded: { gap: "The schema has no join-password field (image env SERVER_PASSWORD is not exposed), so a granted Enshrouded server is open.", note: "Join via address:15637." },
  factorio: { join: "game_password", ids: ["admins"], note: "Multiplayer > Connect to address, address:34197." },
  gmod: { join: "sv_password", admin: ["rcon_password"], workshop: ["workshop_collection"], note: "console: connect <subdomain>.play.nxeon.cloud; password <pw>." },
  conan: { join: "serverPassword", workshop: ["modIds"], note: "Join via address:7777 (Direct Connect)." },
  unturned: { join: "password", note: "Join via address:27015 (Connect)." },
  theforest: { join: "password", admin: ["adminPassword"], note: "Multiplayer > Direct Connect, address:27015." },
  sonsoftheforest: { join: "password", note: "Find by server name in the in-game list; address:8766 query port." },
  bedrock: { note: "Players add the server with the play subdomain AND port 19132. No join password; use the allow-list." },
  terraria: { join: "server-password", note: "Multiplayer > Join via IP, address:7777, then the server password." },
  dragonwilds: { join: "WORLD_PASSWORD", admin: ["ADMIN_PASSWORD"], ids: ["OWNER_ID"], note: "Owner Steam ID and Admin Password are REQUIRED or the server does not appear." },
  sunkenland: { join: "password", joinMax: 8, codes: [{ key: "worldGuid", gen: "uuid" }], note: "Join by Server ID / invite; the World GUID is required to start the server." },
  abioticfactor: { join: "ServerPassword", note: "Join via address:7777 (Direct Connect)." },
  corekeeper: { join: "password", joinMax: 28, codes: [{ key: "gameId", gen: "gameid" }], note: "Players join by the Connect Code (Game ID) + password. A blank Game ID makes the server generate a NEW random one on every start, so nobody can rely on it." },
  icarus: { join: "SERVER_PASSWORD", admin: ["SERVER_ADMIN_PASSWORD"], note: "Find by server name in Join Game; address:17777." },
  arkasa: { join: "ServerPassword", admin: ["AdminPassword"], workshop: ["ModIds"], note: "Find by session name in the server browser (ASA has no direct address join)." },
  soulmask: { join: "SERVER_PASSWORD", admin: ["ADMIN_PASSWORD"], note: "Join via address:8777 or the server list." },
  dst: { join: "PASSWORD", workshop: ["MODS"], note: "The Klei cluster token is required (the server cannot start without one). Players find it by name in the server browser." },
  vintagestory: { join: "Password", note: "Join via address:42420." },
  necesse: { join: "SERVER_PASSWORD", ids: ["SERVER_OWNER"], note: "Join via address:14159; the owner username gets op rights." },
  tf2: { join: "SRCDS_PW", admin: ["SRCDS_RCONPW"], note: "console: connect <address>; password <pw>. A GSLT token is needed to be publicly reachable." },
  l4d2: { admin: ["RCON_PASSWORD"], note: "console: connect <address>. The schema has no join-password field." },
  nightingale: { join: "CONNECTIONPASSWORD", admin: ["ADMINPASSWORD"], note: "Join via address:7777." },
  squad: { workshop: ["MODS"], note: "Join via address:7787 (server browser by name). The schema has no join-password field." },
  kf2: { admin: ["KF2_ADMIN_PASSWORD"], workshop: ["KF2_SERVER_SUBSCRIBED_WORKSHOP_ITEMS"], note: "Join via address:7777. The schema has no join-password field." },
  barotrauma: { join: "PASSWORD", ids: ["OWNER_STEAMNAME", "OWNER_STEAMID"], note: "Join via address:27015." },
  sandstorm: { join: "password", note: "Find by server name; address:27102 (query)." },
  mordhau: { join: "SERVER_PW", admin: ["SERVER_ADMINPW"], note: "Admin password is REQUIRED. Join via address:7777." },
  theisle: { join: "serverPassword", note: "Join via address:7777." },
  stationeers: { join: "STATIONEERS_SERVER_PASSWORD", note: "Join via address:27500." },
  eco: { join: "password", note: "Join via address:3000." },
  empyrion: { join: "serverPassword", note: "Join via address:30000." },
  spaceengineers: { note: "Join via the server list / address:27016. The schema has no join-password field." },
  armareforger: { join: "SERVER_PASSWORD", admin: ["RCON_PASSWORD"], ids: ["ADMINS"], note: "Join via address:2001 (Direct Join)." },
  cs16: { admin: ["rconPassword"], ids: ["adminSteamId"], note: "console: connect <address>. The schema has no join-password field." },
  ets2: { join: "password", ids: ["moderator_list"], note: "Convoy: find by lobby name in the in-game server list." },
  ats: { join: "password", ids: ["moderator_list"], note: "Convoy: find by lobby name in the in-game server list." },
  dayz: { join: "password", admin: ["passwordAdmin"], note: "Join via address:2302 (Direct Connect)." },
  fivem: { join: "sv_password", ids: ["sv_licenseKey"], note: "Legally gated family (no managed FiveM sale without permission); needs the creator's own Cfx.re key and a dedicated IP, so a grant is not supported." },
};

/** True when players connect by a customer-chosen `<sub>.play.nxeon.cloud` name. */
export function needsSubdomainFor(family: string | null | undefined): boolean {
  return family === "minecraft" || family === "bedrock" || (!!family && HOSTNAME_CONNECT_FAMILIES.has(family as GameFamily));
}

export const SUBDOMAIN_MIN_LENGTH = 3;

export type GrantTier = "required" | "recommended" | "advanced";
export type GrantGen = "password" | CodeGen;
export type GrantField = ConfigField & {
  tier: GrantTier;
  /** True when a grant refuses to go ahead while this field is blank/invalid. */
  grantRequired: boolean;
  /** How a default value is generated for this field. */
  generate?: GrantGen;
  /** Plain reason this field matters for connecting. */
  why?: string;
};

const SECRET_RE = /(pass|pw$)/i;
const isSecretLike = (f: ConfigField) => f.type === "string" && SECRET_RE.test(f.key) && !/token|key/i.test(f.key);

/** Length of a generated password for a field: 10 by default, shortened/lengthened to fit the field's own bounds. */
export function generatedPasswordLength(f: ConfigField, joinMax?: number): number {
  const hi = Math.min(f.maxLength ?? 64, joinMax ?? 64);
  return Math.max(f.minLength ?? 1, Math.min(10, hi));
}

/** Generate a fresh value for a field (server-side only for first fill; the form calls this for "Generate another"). */
export function generateFor(f: Pick<GrantField, "generate" | "minLength" | "maxLength">, joinMax?: number): string {
  if (f.generate === "gameid") return suggestGameCode(Math.min(28, f.maxLength ?? 28));
  if (f.generate === "uuid") return suggestUuid();
  return suggestPassword(generatedPasswordLength(f as ConfigField, joinMax));
}

/** The per-game fields a grant must show: the schema, tiered, with generation hints. */
export function grantFieldPlan(family: string): GrantField[] {
  const schema = GAME_CONFIG_SCHEMAS[family];
  if (!schema) return [];
  const spec = CONNECT_SPECS[family] ?? {};
  const codeKeys = new Map((spec.codes ?? []).map((c) => [c.key, c.gen] as const));
  const admin = new Set(spec.admin ?? []);
  const ids = new Set(spec.ids ?? []);
  const workshop = new Set(spec.workshop ?? []);
  return schema.fields.map((f): GrantField => {
    const isJoin = spec.join === f.key;
    const code = codeKeys.get(f.key);
    const grantRequired = (f.type === "string" && !!f.required) || isJoin || code !== undefined;
    let generate: GrantGen | undefined;
    if (code) generate = code;
    else if (f.type === "string" && (isJoin || ((admin.has(f.key) || f.required) && isSecretLike(f)))) generate = "password";
    const tier: GrantTier = grantRequired ? "required" : admin.has(f.key) || ids.has(f.key) || workshop.has(f.key) || f.suggest ? "recommended" : "advanced";
    const why = isJoin ? "The password players type to join." : code ? "A stable code/ID players join by." : admin.has(f.key) ? "Admin / RCON access for the creator." : ids.has(f.key) ? "Identity the game uses for owner/admin rights." : undefined;
    return { ...f, tier, grantRequired, generate, why };
  });
}

/** Initial generated values for a new grant (fresh secrets/codes, never reused between grants). */
export function grantInitialConfig(family: string): Record<string, string> {
  const spec = CONNECT_SPECS[family] ?? {};
  const out: Record<string, string> = {};
  for (const f of grantFieldPlan(family)) {
    if (f.generate) out[f.key] = generateFor(f, f.key === spec.join ? spec.joinMax : undefined);
  }
  return out;
}

export type GrantProblem = { key: string; label: string; message: string };

/**
 * Everything wrong with a grant's connect fields, in plain language. NEVER includes a
 * value in a message (these strings reach the audit log). The server runs this before
 * placing a grant (lib/partner-grants.ts) and the form runs the same rules live, so a
 * disabled Grant button can say exactly which field is missing.
 */
export function grantConnectProblems(family: string, config: Record<string, unknown> | null | undefined, subdomain: string | null | undefined): GrantProblem[] {
  const out: GrantProblem[] = [];
  const cfg = config ?? {};
  if (needsSubdomainFor(family) && (subdomain ?? "").trim().length < SUBDOMAIN_MIN_LENGTH) {
    out.push({ key: "subdomain", label: "Play address (subdomain)", message: `Play address (subdomain) is required — it is how the creator connects (at least ${SUBDOMAIN_MIN_LENGTH} characters).` });
  }
  const fields = grantFieldPlan(family);
  const spec = CONNECT_SPECS[family] ?? {};
  for (const f of fields) {
    const raw = cfg[f.key];
    const p = fieldProblem(f, raw, fields, cfg);
    if (f.grantRequired && p.blank) out.push({ key: f.key, label: f.label, message: `${f.label} is required.` });
    else if (p.ruleError) out.push({ key: f.key, label: f.label, message: p.ruleError });
    else if (spec.join === f.key && spec.joinMax && String(raw ?? "").length > spec.joinMax) out.push({ key: f.key, label: f.label, message: `${f.label} can be at most ${spec.joinMax} characters in this game.` });
  }
  return out;
}

// ---------------------------------------------------------------------------
// What the PLAYER needs (handoff summary, customer Join details card, audit)
// ---------------------------------------------------------------------------

export type JoinItem = { label: string; value: string | null; secret: boolean; missing: boolean; hint?: string };

const blank = (v: unknown) => v === undefined || v === null || String(v).trim() === "";

/** Ordered list of what a player/creator needs, with gaps flagged. `values` = the server's saved gameConfig. */
export function joinItems(family: string, values: Record<string, unknown> | null | undefined): JoinItem[] {
  const schema = GAME_CONFIG_SCHEMAS[family];
  const spec = CONNECT_SPECS[family];
  if (!schema || !spec) return [];
  const v = values ?? {};
  const label = (k: string) => schema.fields.find((f) => f.key === k)?.label ?? k;
  const items: JoinItem[] = [];
  if (spec.join) {
    const miss = blank(v[spec.join]);
    items.push({ label: label(spec.join), value: miss ? null : String(v[spec.join]), secret: true, missing: miss, hint: miss ? "No password is set: players cannot be sure how to join. Set one in Settings." : undefined });
  }
  for (const c of spec.codes ?? []) {
    const miss = blank(v[c.key]);
    items.push({ label: label(c.key), value: miss ? null : String(v[c.key]), secret: false, missing: miss, hint: miss ? (c.key === "gameId" ? "Not set: the server picks a new random code on every start. Set a fixed one in Settings." : "Required to start the server. Set it in Settings.") : undefined });
  }
  for (const k of spec.ids ?? []) {
    if (blank(v[k])) continue;
    items.push({ label: label(k), value: String(v[k]), secret: /license/i.test(k), missing: false });
  }
  for (const k of spec.admin ?? []) {
    if (blank(v[k])) continue;
    items.push({ label: label(k), value: String(v[k]), secret: SECRET_RE.test(k), missing: false });
  }
  return items;
}

/** Families whose join details are incomplete for a given saved config (audit + customer card). */
export function joinGaps(family: string, values: Record<string, unknown> | null | undefined, subdomain: string | null | undefined): string[] {
  const gaps: string[] = [];
  if (needsSubdomainFor(family) && !(subdomain ?? "").trim()) gaps.push("no play subdomain (players must use a raw IP:port)");
  for (const f of grantFieldPlan(family)) {
    if (f.grantRequired && blank((values ?? {})[f.key])) gaps.push(`${f.label} is blank`);
  }
  const spec = CONNECT_SPECS[family];
  if (spec?.gap) gaps.push(`schema gap: ${spec.gap}`);
  return gaps;
}

/** Ports a player connects on, "27015/udp, ..." — from the same table the provisioner forwards. */
export function portsText(family: string): string {
  try {
    return joinPortsFor(family as GameFamily).map((p) => `${p.port}/${p.protocol}`).join(", ");
  } catch {
    return "";
  }
}

