    // A guest has no account to check against; the quote still refuses a taken name, and the
    // live check runs once they sign up and resume at /dashboard/deploy.
    if (!(o.service === "game" && game?.needsSubdomain) || cat.guest) { setGameSubCheck({ status: "idle" }); return; }
