    if (sub.length < 3) { setGameSubCheck({ status: "idle" }); return; }
    setGameSubCheck({ status: "checking" });
    let cancelled = false;
    const t = setTimeout(async () => {
      try {
        const r = await checkGameSubdomain(sub);
        if (cancelled) return;
        if (!r.available) setGameSubCheck({ status: "bad", reason: r.reason });
        else setGameSubCheck({ status: "ok" });
      } catch {
        if (!cancelled) setGameSubCheck({ status: "bad", reason: "Couldn't check right now — try again." });
      }
    }, 400);
    return () => { cancelled = true; clearTimeout(t); };
  }, [o.subdomain, o.service, game?.needsSubdomain, cat.guest]);

