new='''/** One schema-driven field (all types), the same inputs the wizard offers. */
function GrantFieldInput({ f, value, onChange, error, missing }: { f: GrantField; value: string; onChange: (v: string) => void; error: string | null; missing: boolean }) {
  const bad = missing ? " border-red-500/60" : "";
  return (
    <label className="block">
      <span className="label flex items-baseline justify-between gap-2">
        <span>{f.label}{f.grantRequired ? " *" : ""}</span>
        {f.generate && (
          <button type="button" className="text-[11px] font-semibold text-brand-300 hover:underline" onClick={(e) => { e.preventDefault(); onChange(generateFor(f)); }}>
            {f.generate === "password" ? "Generate strong password" : f.generate === "uuid" ? "Generate GUID" : "Generate code"}
          </button>
        )}
      </span>
      {f.type === "enum" ? (
        <select className={"input w-full" + bad} value={value} onChange={(e) => onChange(e.target.value)}>
          {f.options?.map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}
        </select>
      ) : f.type === "bool" ? (
        <span className="flex h-9 items-center gap-2 text-slate-300"><input type="checkbox" checked={value === "true"} onChange={(e) => onChange(e.target.checked ? "true" : "false")} /> {f.help ?? "Enabled"}</span>
      ) : (
        <input className={"input w-full" + (f.generate ? " font-mono" : "") + bad} type={f.type === "int" ? "number" : "text"} min={f.min} max={f.max} maxLength={256}
               value={value} onChange={(e) => onChange(e.target.value)} spellCheck={false} autoComplete="off" />
      )}
      {error ? <span className="text-[11px] text-red-400">{error}</span> : f.help && f.type !== "bool" ? <span className="text-[11px] text-slate-500">{f.help}</span> : f.why ? <span className="text-[11px] text-slate-500">{f.why}</span> : null}
    </label>
  );
}

function HandoffCard({ h, onClose }: { h: GrantHandoff; onClose: () => void }) {
  return (
    <div className="space-y-3 rounded-lg border border-emerald-500/30 bg-emerald-500/[0.05] p-4">
      <div className="flex items-start justify-between gap-3">
        <div>
          <h4 className="font-semibold text-emerald-300">Granted: hand these details to the creator</h4>
          <p className="text-xs text-slate-400">The server is provisioning now. These are also on the creator&apos;s server page (Network tab, Join details). Contains secrets: do not paste into a public channel.</p>
        </div>
        <button type="button" className="text-xs text-slate-400 hover:underline" onClick={onClose}>Dismiss</button>
      </div>
      <dl className="space-y-2 text-sm">
        <div className="flex flex-wrap items-center gap-2"><dt className="w-40 text-slate-400">Connect address</dt><dd className="flex items-center gap-2"><code className="rounded bg-black/30 px-2 py-0.5 font-mono text-xs">{h.address ?? "assigned when provisioning finishes"}</code>{h.address && <CopyText text={h.address} />}</dd></div>
        {h.subdomain && <div className="flex flex-wrap items-center gap-2"><dt className="w-40 text-slate-400">Subdomain</dt><dd className="flex items-center gap-2"><code className="rounded bg-black/30 px-2 py-0.5 font-mono text-xs">{h.subdomain}</code><CopyText text={h.subdomain} /></dd></div>}
        {h.ports && <div className="flex flex-wrap items-center gap-2"><dt className="w-40 text-slate-400">Port(s)</dt><dd className="font-mono text-xs">{h.ports}</dd></div>}
