            <dd className="flex items-center gap-2">{it.value ? <><code className="rounded bg-black/30 px-2 py-0.5 font-mono text-xs">{it.value}</code><CopyText text={it.value} /></> : <span className="text-amber-300">not set{it.hint ? `: ${it.hint}` : ""}</span>}</dd></div>
        ))}
      </dl>
      {h.note && <p className="text-xs text-slate-400">{h.note}</p>}
      <ol className="list-decimal space-y-1 pl-5 text-xs text-slate-400">{h.steps.map((x) => <li key={x}>{x}</li>)}</ol>
      {h.gaps.length > 0 && <ul className="list-disc space-y-1 pl-5 text-xs text-amber-300">{h.gaps.map((x) => <li key={x}>{x}</li>)}</ul>}
      <div className="flex items-center gap-2"><CopyText text={h.text} label="Copy all details" /></div>
    </div>
  );
}

export function PartnerGrantForm({ partnerId, hasAccount, activeCount }: { partnerId: string; hasAccount: boolean; activeCount: number }) {
  const router = useRouter();
  const [open, setOpen] = useState(false);
  const [opts, setOpts] = useState<Opts | null>(null);
  const [planId, setPlanId] = useState("");
  const [fields, setFields] = useState<Fields | null>(null);
  const [term, setTerm] = useState(1);
  const [region, setRegion] = useState("");
  const [variant, setVariant] = useState("");
  const [cfg, setCfg] = useState<Record<string, string>>({});
  const [subdomain, setSubdomain] = useState("");
  const [subCheck, setSubCheck] = useState<{ status: "idle" | "checking" | "ok" | "bad"; reason?: string }>({ status: "idle" });
  const [reason, setReason] = useState("");
  const [onExpiry, setOnExpiry] = useState<"EXPIRE" | "RENEW_WALLET">("EXPIRE");
  const [msg, setMsg] = useState<{ ok: boolean; text: string } | null>(null);
  const [handoff, setHandoff] = useState<GrantHandoff | null>(null);
  const [pending, start] = useTransition();

  useEffect(() => { if (open && !opts) partnerGrantFormOptions().then(setOpts).catch(() => setMsg({ ok: false, text: "Couldn't load options." })); }, [open, opts]);
  useEffect(() => {
    if (!planId) { setFields(null); return; }
    partnerGrantGameFields(planId).then((f) => {
      if ("error" in f) { setFields(null); return; }
      setFields(f); setVariant(f.defaultVariant); setSubdomain(""); setSubCheck({ status: "idle" });
      // Schema defaults for untouched fields come from the server on submit; start from the order defaults + generated secrets/codes.
      setCfg({ ...f.orderDefaults, ...f.initial });
    });
  }, [planId]);
  // Live "is this name free" check, same debounce idiom as the deploy wizard.
  useEffect(() => {
    if (!fields?.needsSubdomain) { setSubCheck({ status: "idle" }); return; }
    const sub = subdomain.trim().toLowerCase();
    if (sub.length < SUBDOMAIN_MIN_LENGTH) { setSubCheck({ status: "idle" }); return; }
    setSubCheck({ status: "checking" });
    let cancelled = false;
    const t = setTimeout(async () => {
      try { const r = await checkGameSubdomain(sub); if (!cancelled) setSubCheck(r.available ? { status: "ok" } : { status: "bad", reason: r.reason }); }
      catch { if (!cancelled) setSubCheck({ status: "bad", reason: "Couldn't check right now." }); }
    }, 400);
    return () => { cancelled = true; clearTimeout(t); };
  }, [subdomain, fields?.needsSubdomain]);

  const families = opts ? [...new Set(opts.plans.map((p) => p.gameFamily))] : [];
  const [family, setFamily] = useState("");
  const plans = opts?.plans.filter((p) => p.gameFamily === family) ?? [];
  const chosen = opts?.plans.find((p) => p.id === planId);

  // The SAME rules the server enforces (lib/game-connect.ts grantConnectProblems), so the hint under
  // the button names exactly the field the server would refuse.
  const problems = fields ? grantConnectProblems(fields.family, cfg, subdomain) : [];
  const hints: string[] = [];
  if (!planId) hints.push(family ? "Choose a plan." : "Choose a game and a plan.");
  for (const p of problems) hints.push(p.message);
  if (fields?.needsSubdomain && subCheck.status === "bad") hints.push(`Play address: ${subCheck.reason ?? "not available"}`);
  if (fields?.needsSubdomain && subCheck.status === "checking") hints.push("Checking that the play address is free…");
  if (reason.trim().length < 3) hints.push("Reason is required (at least 3 characters, kept in the audit trail).");
  const canGrant = !pending && hints.length === 0;

  if (!hasAccount) return <p className="text-sm text-slate-500">This partner has no linked account yet — a server can only be granted once they&apos;ve claimed their invite and signed in.</p>;
  if (!open) return <button type="button" className="btn-secondary h-9 px-4" onClick={() => setOpen(true)}>Grant a free game server…</button>;

  const submit = () => start(async () => {
    setMsg(null);
    const r = await grantPartnerGameServer({
      partnerId, gamePlanId: planId, termMonths: term, region: region || undefined, variant: variant || undefined,
      config: cfg, subdomain: subdomain.trim() || undefined, reason, onExpiry,
    });
    if (r.error) setMsg({ ok: false, text: r.error });
    else { setMsg({ ok: true, text: "Granted — the server is provisioning now." }); setHandoff(r.handoff ?? null); router.refresh(); }
  });

  const set = (k: string, v: string) => setCfg((c) => ({ ...c, [k]: v }));
  const byKey = new Map(problems.map((p) => [p.key, p.message] as const));
  const renderField = (f: GrantField) => (
    <GrantFieldInput key={f.key} f={f} value={cfg[f.key] ?? String(f.default)} onChange={(v) => set(f.key, v)}
                     error={f.type === "string" ? (byKey.get(f.key) ?? null) : null} missing={byKey.has(f.key)} />
  );
