cd /tank/nxeon-wt-grants && cat > scripts/audit-grants.ts <<'EOF'
/**
 * READ-ONLY audit of every admin-granted game server: each PartnerGrant that has a server, plus any
 * other game server flagged isFree (admin-comped). For each it checks the connect essentials the
 * grant form now requires (lib/game-connect.ts joinGaps: play subdomain for hostname-connect families,
 * join password, connect code / world ID, schema-required fields) against the server's SAVED gameConfig.
 *
 *   npx tsx scripts/audit-grants.ts            # table, changes nothing (dry-run is the only mode)
 *   npx tsx scripts/audit-grants.ts --json     # machine-readable
 *   npx tsx scripts/audit-grants.ts --all      # also list servers with no gaps
 *
 * It only SELECTs. It never prints a password or code value (only "set" / "BLANK"), so its output is
 * safe to paste into a ticket. Exit code 1 when any server has a gap, 0 when clean, 2 on error.
 * Fixes are a separate, owner-run step: docs/GRANT-CONNECT-AUDIT.md section "Waasephi fix procedure".
 */
import { db } from "../lib/db";
import { CONNECT_SPECS, joinGaps, joinItems, needsSubdomainFor } from "../lib/game-connect";
import { validateConfig } from "../lib/game-config";

type Row = {
  serverId: string; hostname: string; family: string; source: "grant" | "isFree"; grantStatus: string | null;
  partner: string | null; status: string; subdomain: string | null;
  fields: { label: string; state: "set" | "BLANK" }[]; gaps: string[];
};

async function main() {
  const json = process.argv.includes("--json");
  const all = process.argv.includes("--all");
  const sel = {
    id: true, hostname: true, status: true, subdomain: true, gameConfig: true, isFree: true,
    gamePlan: { select: { gameFamily: true } }, osTemplate: { select: { family: true } },
  } as const;
  const grants = await db.partnerGrant.findMany({ where: { serverId: { not: null } }, select: { serverId: true, status: true, partner: { select: { name: true } } } });
  const byServer = new Map(grants.map((g) => [g.serverId as string, g]));
  const servers = await db.server.findMany({
    where: { gamePlanId: { not: null }, status: { not: "DELETING" }, OR: [{ id: { in: [...byServer.keys()] } }, { isFree: true }] },
    select: sel,
  });
  const rows: Row[] = [];
  for (const s of servers) {
    const family = s.gamePlan?.gameFamily ?? s.osTemplate?.family ?? "";
    if (!family || !CONNECT_SPECS[family]) continue;
    const g = byServer.get(s.id);
    // Same coercion the customer's page uses, so a stored value is judged as the customer sees it.
    const v = validateConfig(family, (s.gameConfig as Record<string, unknown> | null) ?? {});
    const values = v.ok ? v.values : ((s.gameConfig as Record<string, unknown> | null) ?? {});
    const gaps = joinGaps(family, values, s.subdomain);
    if (!v.ok) gaps.push("saved settings fail validation (" + v.error.replace(/"[^"]*"/g, "…") + ")");
    rows.push({
      serverId: s.id, hostname: s.hostname, family, source: g ? "grant" : "isFree", grantStatus: g?.status ?? null,
      partner: g?.partner.name ?? null, status: s.status, subdomain: needsSubdomainFor(family) ? s.subdomain : null,
      fields: joinItems(family, values).map((i) => ({ label: i.label, state: i.value ? "set" : "BLANK" })), gaps,
    });
  }
  const bad = rows.filter((r) => r.gaps.length > 0);
  if (json) console.log(JSON.stringify(all ? rows : bad, null, 2));
  else {
    console.log(`${rows.length} admin-granted / comped game server(s) checked, ${bad.length} with connect gaps.\n`);
    for (const r of all ? rows : bad) {
      console.log(`${r.hostname}  [${r.family}]  ${r.source}${r.grantStatus ? `:${r.grantStatus}` : ""}${r.partner ? `  partner=${r.partner}` : ""}  status=${r.status}  id=${r.serverId}`);
      console.log(`   fields: ${r.fields.map((f) => `${f.label}=${f.state}`).join(", ") || "(none)"}`);
      for (const g of r.gaps) console.log(`   GAP: ${g}`);
    }
  }
  await db.$disconnect();
  process.exit(bad.length ? 1 : 0);
}

main().catch(async (e) => {
  console.error(e);
  await db.$disconnect().catch(() => {});
  process.exit(2);
});
EOF
