    const cfg = grantInitialConfig(fam);
    const userSupplied = new Set(
      grantFieldPlan(fam).filter((f) => f.grantRequired && !f.generate && f.type === "string").map((f) => f.key),
    );
    const problems = grantConnectProblems(fam, cfg, "creator-sub").filter((p) => !userSupplied.has(p.key));
    assert.deepEqual(problems, [], `${fam}: ${JSON.stringify(problems)}`);
  }
});

test("generated values also pass validateConfig (what placeGameOrder runs) wherever the rest is valid", () => {
  for (const fam of FAMILIES) {
    if (fam === "fivem") continue; // gated family: needs a licence key + dedicated IP
    const cfg = { ...grantInitialConfig(fam) };
    // Fill the creator-supplied required fields with a plausible value.
    for (const f of grantFieldPlan(fam)) if (f.grantRequired && !f.generate && f.type === "string") cfg[f.key] = "76561198000000000";
    const r = validateConfig(fam, cfg);
    assert.ok(r.ok, `${fam}: ${r.ok ? "" : r.error}`);
  }
});

test("Core Keeper: Connect Code is generated 15-28 chars and the join password is required", () => {
  const cfg = grantInitialConfig("corekeeper");
  assert.match(cfg.gameId, /^[A-Za-z0-9]{15,28}$/);
  assert.ok(cfg.password.length >= 8 && cfg.password.length <= 28);
  const miss = grantConnectProblems("corekeeper", { worldName: "x" }, "");
  assert.deepEqual(miss.map((p) => p.key).sort(), ["gameId", "password"]);
  assert.equal(grantConnectProblems("corekeeper", { gameId: "short", password: "abcdefgh" }, "").some((p) => p.key === "gameId"), true);
  assert.equal(validateConfig("corekeeper", { gameId: "tooshort" }).ok, false);
  assert.equal(validateConfig("corekeeper", { gameId: "" }).ok, true, "blank stays valid for the normal wizard / existing servers");
});

test("Terraria: server password required for a grant, generated by default", () => {
  assert.deepEqual(grantConnectProblems("terraria", {}, "").map((p) => p.key), ["server-password"]);
  assert.equal(grantConnectProblems("terraria", grantInitialConfig("terraria"), "").length, 0);
});

test("Sunkenland: password never exceeds the game's 8-char limit; world GUID generated", () => {
  const cfg = grantInitialConfig("sunkenland");
  assert.ok(cfg.password.length <= 8);
  assert.match(cfg.worldGuid, /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/);
  assert.ok(grantConnectProblems("sunkenland", { password: "123456789", worldGuid: cfg.worldGuid }, "").some((p) => p.key === "password"));
});

test("hostname-connect families need a play subdomain; others do not", () => {
  for (const fam of [...HOSTNAME_CONNECT_FAMILIES, "minecraft", "bedrock"]) {
    assert.equal(needsSubdomainFor(fam), true, fam);
    assert.ok(grantConnectProblems(fam, grantInitialConfig(fam), "").some((p) => p.key === "subdomain"), fam);
    assert.ok(!grantConnectProblems(fam, grantInitialConfig(fam), "abc").some((p) => p.key === "subdomain"), fam);
  }
  assert.equal(needsSubdomainFor("terraria"), false);
});

test("problem messages never contain a secret value", () => {
  const cfg = { SERVER_PASS: "ab", world: "Dedicated" };
  const msgs = grantConnectProblems("valheim", cfg, "").map((p) => p.message).join(" ");
  assert.ok(!msgs.includes("ab ") && !/\bab\b/.test(msgs.replace(/at least|characters/g, "")));
});

test("schema-required fields stay required (Valheim password, DST token, Dragonwilds owner)", () => {
  assert.ok(grantConnectProblems("valheim", {}, "").some((p) => p.key === "SERVER_PASS"));
  assert.ok(grantConnectProblems("dst", grantInitialConfig("dst"), "abc").some((p) => p.key === "TOKEN"));
  assert.ok(grantConnectProblems("dragonwilds", grantInitialConfig("dragonwilds"), "").some((p) => p.key === "OWNER_ID"));
});

test("fieldProblem: the one shared verdict (blank-required, minLength, notInsideField)", () => {
  const fields = GAME_CONFIG_SCHEMAS.valheim.fields;
  const pass = fields.find((f) => f.key === "SERVER_PASS")!;
  assert.equal(fieldProblem(pass, undefined, fields, {}).missing, true);
  assert.equal(fieldProblem(pass, "abc", fields, {}).ruleError !== null, true);
  assert.equal(fieldProblem(pass, "abcdefgh", fields, { world: "xyz" }).missing, false);
  assert.equal(fieldProblem(pass, "dedi", fields, { world: "Dedicated" }).missing, true);
});

test("generators: lengths and charset", () => {
  for (let i = 0; i < 50; i++) assert.match(suggestGameCode(), /^[A-Za-z0-9]{28}$/);
  assert.notEqual(suggestUuid(), suggestUuid());
  assert.ok(generateFor({ generate: "password", minLength: 5 }).length >= 5);
});

test("joinItems / joinGaps flag a blank Core Keeper code and password, never leak by omission", () => {
  const items = joinItems("corekeeper", { gameId: "", password: "" });
  assert.ok(items.every((i) => i.missing));
  assert.ok(joinGaps("corekeeper", { gameId: "", password: "" }, null).length >= 2);
  const ok = joinItems("corekeeper", { gameId: "A".repeat(20), password: "secret1234" });
  assert.ok(ok.every((i) => !i.missing));
});

test("handoff carries address, subdomain, password, code and a copyable block", () => {
  const h = buildGrantHandoff({ family: "corekeeper", gameName: "Core Keeper", address: "1.2.3.4:27015", subdomain: null, values: { gameId: "A".repeat(20), password: "pw123456" }, serverId: "s1" });
  assert.match(h.text, /Address: 1\.2\.3\.4:27015/);
  assert.match(h.text, /Connect Code: A{20}/);
  assert.match(h.text, /Server Password: pw123456/);
  assert.ok(h.steps.length >= 2);
});

test("grant wiring: server-side guard is in grantPartnerServer BEFORE the order is placed", () => {
  const src = readFileSync(new URL("../lib/partner-grants.ts", import.meta.url), "utf8");
  const guard = src.indexOf("grantConnectProblems(");
  assert.ok(guard > 0);
  assert.ok(guard < src.indexOf("await gameOrderQuote(intent"), "guard must precede the quote");
  assert.ok(guard < src.indexOf("await placeGameOrder("), "guard must precede placement");
  assert.ok(!/console\.(log|error)\([^)]*config/i.test(src), "no config logging in the grant path");
});

test("grant billing wording: Free until / Renews at (only RENEW_WALLET)", () => {
  const exp = new Date("2026-11-02T12:00:00Z");
  const free = grantRenewalText({ onExpiry: "EXPIRE", status: "ACTIVE" }, exp, "$11.50/mo");
  assert.equal(free?.label, "Free until Nov 2, 2026");
  assert.equal(free?.free, true);
  const renew = grantRenewalText({ onExpiry: "RENEW_WALLET", status: "ACTIVE" }, exp, "$11.50/mo");
  assert.equal(renew?.label, "Renews at $11.50/mo on Nov 2, 2026");
  assert.equal(renew?.free, false);
  assert.equal(grantRenewalText({ onExpiry: "EXPIRE", status: "EXPIRING" }, exp, "x")?.free, true);
  assert.equal(grantRenewalText({ onExpiry: "RENEW_WALLET", status: "REVOKED" }, exp, "x")?.free, true, "revoked: runs out its term, no charge");
  // converted / expired / no grant: ordinary server wording
  assert.equal(grantRenewalText({ onExpiry: "EXPIRE", status: "CONVERTED" }, exp, "x"), null);
  assert.equal(grantRenewalText({ onExpiry: "EXPIRE", status: "EXPIRED" }, exp, "x"), null);
  assert.equal(grantRenewalText(null, exp, "x"), null);
  assert.equal(isGrantFree({ onExpiry: "RENEW_WALLET", status: "ACTIVE" }), false);
});
