// ---------------------------------------------------------------------------
// Danger Zone: wipe & reinstall THE GAME (same family) — never the VPS/VM.
// See worker/game-control.ts's gameReinstall for exactly what runs.
// ---------------------------------------------------------------------------

/**
 * Wipe this server's game data and re-run its setup script against the SAME
 * VM — enqueues GAME_REINSTALL. Requires the literal confirmation text
 * "WIPE" (case-insensitive) since this permanently destroys the world/save
 * data with no undo, the same discipline `reinstallToOs`'s "ERASE" confirm
 * uses for the VPS-level equivalent.
 *
 * Deliberately does NOT support switching to a different game family — that
 * needs a different OsTemplate/GamePlan/ports/RCON setup and is real,
 * separable work; see gameReinstall's own doc comment. This only ever
 * reinstalls the CURRENT family.
 */
export async function reinstallGame(serverId: string, confirmText: string): Promise<Result> {
  try {
    const { user, server } = await ownedServer(serverId);
    const spec = requireSpec(server);
    if (confirmText.trim().toUpperCase() !== "WIPE") {
      return { ok: false, error: 'Type "WIPE" to confirm.' };
    }
    const limited = throttle(user.id, "reinstall", 3);
    if (limited) return { ok: false, error: limited };
    if (server.status !== "RUNNING")
      return { ok: false, error: "The VPS must be running to reinstall the game." };
    if (await lifecycleBusy(server.id))
      return { ok: false, error: "Another server operation is in progress — try again shortly." };
    if (await gameJobInflight(server.id))
      return { ok: false, error: "A game control action is already in progress on this server." };

    await db.job.create({ data: { type: "GAME_REINSTALL", serverId: server.id } });
    await db.auditLog.create({
      data: { userId: user.id, action: "gameserver.reinstall", detail: `${spec.family} on ${server.hostname}` },
    });
    revalidatePath(`/dashboard/servers/${serverId}`);
    return { ok: true };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

