/**
 * Owner-run fix for the two 2026-10-02 Waasephi grants (see docs/GRANT-CONNECT-AUDIT.md,
 * "Waasephi fix procedure"). NOT executed by the agent that wrote it.
 *
 *   npx tsx scripts/fix-waasephi-grants.ts                 # DRY RUN (default): shows what would change, masked, writes nothing
 *   NXEON_DB_TARGET=nxeon npx tsx scripts/fix-waasephi-grants.ts --apply
 *
 * What --apply does (and nothing else):
 *   corekeeper-mun0p2  Server.gameConfig: set a stable Connect Code (gameId, 28 chars) and a known join password
 *                      (only the fields that are currently blank; an existing value is never overwritten).
 *   terraria-rus8hk    Server.gameConfig: set server-password if blank.
 * It prints each generated value ONCE on stdout so the owner can hand it to the creator; values are never
 * written to the audit log. It does NOT restart anything and does NOT enqueue a GAME_REINSTALL: the new
 * config only reaches the running container through the next step in the doc (Save & apply once the
 * appliers ship, or a GAME_REINSTALL, which wipes the new empty world).
 */
import { db } from "../lib/db";
import { assertDbTarget } from "./db-target-guard";
import { validateConfig } from "../lib/game-config";
import { CONNECT_SPECS, generateFor, grantFieldPlan } from "../lib/game-connect";

const TARGETS = ["corekeeper-mun0p2", "terraria-rus8hk"];

async function main() {
  const apply = process.argv.includes("--apply");
  if (apply) assertDbTarget("fix-waasephi-grants");
  else console.log("DRY RUN: nothing will be written. Re-run with --apply (and NXEON_DB_TARGET) to change the two servers.\n");

  let changed = 0;
  for (const hostname of TARGETS) {
    const s = await db.server.findFirst({
      where: { hostname },
      select: { id: true, hostname: true, status: true, gameConfig: true, gamePlan: { select: { gameFamily: true } }, osTemplate: { select: { family: true } } },
    });
    if (!s) { console.log(`${hostname}: NOT FOUND (skipped)`); continue; }
    const family = s.gamePlan?.gameFamily ?? s.osTemplate?.family ?? "";
    const spec = CONNECT_SPECS[family];
    if (!spec) { console.log(`${hostname}: unknown family ${family} (skipped)`); continue; }
    const cur = ((s.gameConfig as Record<string, unknown> | null) ?? {}) as Record<string, unknown>;
    const next: Record<string, unknown> = { ...cur };
    const made: string[] = [];
    for (const f of grantFieldPlan(family)) {
      // Only the connect essentials, only when blank.
      if (!f.grantRequired || !f.generate) continue;
      const v = cur[f.key];
      if (v !== undefined && v !== null && String(v).trim() !== "") continue;
      next[f.key] = generateFor(f, f.key === spec.join ? spec.joinMax : undefined);
      made.push(f.key);
    }
