    await db.auditLog.create({ data: { userId: null, action: "partner.grant_connect_fix", detail: `server=${s.id} family=${family} set=${made.join(",")}` } });
    for (const k of made) console.log(`   ${k} = ${String(next[k])}   (shown once; also visible in the server's Settings and Network > Join details)`);
    changed++;
  }
  console.log(apply ? `\nDone: ${changed} server(s) updated in the database. Config is saved but NOT yet in the running containers — see the doc.` : "\n(dry run complete)");
  await db.$disconnect();
}

